+	if (!ident || ident.trim() === '') {
+		return false;
+	}
+
+	// trims, removes ISO 10646 characters, and singly-escaped characters
+	const trimmedIdent = ident
+		.trim()
+		.replace(ISO_10646_CHARACTERS, '')
+		.replace(SINGLE_ESCAPED_CHARACTERS, '');
