+					if (isDuplicate) {
+						report({
+							message: messages.rejected,
+							messageArgs: [selectorStr],
+							node: keyframeRule,
+							result,
+							ruleName,
+							index,
+							endIndex,
+						});
+
+						return;
+					}
+
+					selectors.add(normalizedSelector);
+				});
+			});
+		});
+	};
+};
