+				const { number, unit } = getDimension(valueNode);
+
+				if (!number || !unit || primaryValues.includes(unit.toLowerCase())) {
+					return;
+				}
+
+				if (
+					'prop' in node &&
+					secondaryOptions &&
+					optionsMatches(secondaryOptions.ignoreProperties, unit.toLowerCase(), node.prop)
+				) {
+					return;
+				}
