+		...source1,
+	};
+
+	for (const [name, syntax] of Object.entries(source2)) {
+		target[name] = mergeSyntax(target[name], syntax);
+	}
+
+	return target;
+}
+
+/**
+ * @param {Array<string> | undefined} source1
+ * @param {Array<string> | undefined} source2
+ * @returns {Array<string> | undefined}
+ */
