+				report({
+					message: messages.expected,
+					messageArgs: [functionName, expectedFunctionName],
+					node: decl,
+					index,
+					endIndex,
+					result,
+					ruleName,
+					fix: {
+						apply: fix,
+						node: decl,
+					},
+				});
+			});
+		});
+	};
