+	const first = node.nodes[firstIndex];
+	let last = node.nodes[lastIndex];
+
+	if (!first || !last) {
+		const selector = node.toString().trim();
+		const index = node.sourceIndex ?? 0;
+		const endIndex = index + selector.length;
