+	// Percentages
+	if (/^(?:\d+|\d*\.\d+)%$/.test(selector)) {
+		return true;
+	}
+
+	if (HAS_TIMELINE_RANGE.test(selector)) {
+		return true;
+	}
+
+	return false;
+}
