+/**
+ * @param {Problem} problem
+ * @param {number} line
+ * @returns {boolean}
+ */
+function isFixApplied({ fix, result: { stylelint }, ruleName }, line) {
+	if (!fix) return false;
+
+	const { disabledRanges, config = {}, fixersData } = stylelint;
